/*
 * testme-sans-incorpora.js — i byte del carattere da mettere DENTRO un documento.
 * GENERATO da tools/font/prepara-font.py — non modificare a mano.
 *
 * Sottoinsieme dei glifi (latino esteso, greco, punteggiatura, matematica,
 * frecce, forme) compresso in WOFF. Serve perche un documento che chiede il
 * carattere a un percorso non lo ottiene: la finestra che stampa il PDF carica
 * da `data:`, origine opaca, dove un `file://` e bloccato — misurato il 18/8,
 * ed era il motivo per cui il PDF usciva nel carattere sbagliato.
 *
 * window.MappAIInc_testme_sans.facce(famiglia) → le @font-face con i byte incorporati.
 */
(function () {
  "use strict";
  var N = "";
  var G = "";
  function faccia(fam, b64, peso) {
    if (!b64) return "";
    return "@font-face{font-family:'" + fam + "';src:url(data:font/woff;base64," + b64 +
      ") format('woff');font-weight:" + peso + ";font-style:normal;font-display:swap;}";
  }
  window.MappAIInc_testme_sans = {
    facce: function (fam) { return faccia(fam, N, 400) + "\n" + faccia(fam, G, 700); }
  };
})();
